/**
 * Measure string and return width, height, left margin, and baseline (top)
 */
int ui_psf2_bbox(void *fnt, char *str, char *end, int *w, int *h, int *l, int *t)
{
    ui_psf2_t *font = (ui_psf2_t*)fnt;
    uint32_t c;
    int mw = 0;

    if(!fnt || !str || !w || !h) return -1;
    if(h) *h = font->height;
    if(w) *w = 0;
    if(l) *l = 0;
    if(t) *t = 0;
    while(*str && (!end || str < end)) {
        if((*str & 128) != 0) {
            if(!(*str & 32)) { c = ((*str & 0x1F)<<6)|(*(str+1) & 0x3F); str += 2; } else
            if(!(*str & 16)) { c = ((*str & 0xF)<<12)|((*(str+1) & 0x3F)<<6)|(*(str+2) & 0x3F); str += 3; } else
            if(!(*str & 8)) { c = ((*str & 0x7)<<18)|((*(str+1) & 0x3F)<<12)|((*(str+2) & 0x3F)<<6)|(*(str+3) & 0x3F); str += 4; }
            else break;
        } else c = *str++;
        if(!c) break;
        switch(c) {
            case '\r': mw = 0; break;
            case '\n': mw = 0; if(h) *h += font->height; break;
            default: mw += (font->width + 1); if(w && mw > *w) *w = mw; break;
        }
    }
    return 0;
}

/**
 * Draw an UTF-8 string to the given pixel buffer
 */
int ui_psf2_draw(void *fnt, char *str, char *end, uint8_t *dst, uint32_t color, int x, int y, int l, int t, int p,
    int cx0, int cy0, int cx1, int cy1)
{
    ui_psf2_t *font = (ui_psf2_t*)fnt;
    uint32_t c, ox = x, X, Y, line, mask, offs, bpl = (font->width + 7) >> 3;
    uint8_t *glyph;

    (void)l; (void)t;
    if(!dst || !str || cx1 < 1 || cy1 < 1 || p < 4) return -1;
    if(x >= cx1 || y >= cy1) return 0;
    while(*str && (!end || str < end)) {
        if((*str & 128) != 0) {
            if(!(*str & 32)) { c = ((*str & 0x1F)<<6)|(*(str+1) & 0x3F); str += 2; } else
            if(!(*str & 16)) { c = ((*str & 0xF)<<12)|((*(str+1) & 0x3F)<<6)|(*(str+2) & 0x3F); str += 3; } else
            if(!(*str & 8)) { c = ((*str & 0x7)<<18)|((*(str+1) & 0x3F)<<12)|((*(str+2) & 0x3F)<<6)|(*(str+3) & 0x3F); str += 4; }
            else break;
        } else c = *str++;
        if(!c) break;
        switch(c) {
            case '\r': x = ox; break;
            case '\n': x = ox; y += font->height; break;
            default:
                glyph = (uint8_t*)fnt + font->headersize + (c > 0 && c < font->numglyph ? c : 0) * font->bytesperglyph;
                offs = y * p + x * 4;
                for(Y = 0; Y < font->height && y + Y < (uint32_t)cy1; Y++, glyph += bpl, offs += p)
                    for(line = offs, mask = 1 << (font->width - 1), X = 0; X < font->width &&
                      y + Y >= (uint32_t)cy0 && x + X < (uint32_t)cx1 && mask; X++, mask >>= 1, line += 4)
                        if(x + X >= (uint32_t)cx0 && *((uint64_t*)glyph) & mask) *((uint32_t*)(dst + line)) = color;
                x += (font->width + 1);
            break;
        }
    }
    return 0;
}

